class Solution {
public:
    string makeSmallestPalindrome(string s) {
        int l = 0, r = s.size() - 1;
        while (l < r) {
            if (s[l] != s[r]) {
                char m = min(s[l], s[r]);
                s[l] = s[r] = m;
            }
            l++; r--;
        }
        return s;
    }
};

