class Solution {
    public String makeSmallestPalindrome(String s) {
        char[] a = s.toCharArray();
        int l = 0, r = a.length - 1;
        while (l < r) {
            if (a[l] != a[r]) {
                char m = (char) Math.min(a[l], a[r]);
                a[l] = m; a[r] = m;
            }
            l++; r--;
        }
        return new String(a);
    }
}

