var makeSmallestPalindrome = function(s) {
    const a = s.split('');
    let l = 0, r = a.length - 1;
    while (l < r) {
        if (a[l] !== a[r]) {
            const m = a[l] < a[r] ? a[l] : a[r];
            a[l] = m; a[r] = m;
        }
        l++; r--;
    }
    return a.join('');
};
